-- Author-scoped cursor reads preserve the same feed ordering.
CREATE INDEX IF NOT EXISTS idx_cf_posts_author_page ON friendbook_cf_firestore_documents(parent_path,json_extract(document_json,'$.authorId'),(CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN 2 ELSE 4 END),(CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN json_extract(document_json,'$.createdAt') ELSE json_extract(document_json,'$.createdAt.millis') END),doc_id) WHERE parent_path='posts';
CREATE INDEX IF NOT EXISTS idx_cf_legacy_posts_author_page ON friendbook_cf_documents(collection,(CASE WHEN json_type(document_json,'$.fields')='object' THEN json_extract(document_json,'$.fields.authorId.stringValue') ELSE json_extract(document_json,'$.authorId') END),(CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN 2 ELSE 4 END),(CASE WHEN json_type(document_json,'$.createdAt') IN ('integer','real') THEN json_extract(document_json,'$.createdAt') ELSE json_extract(document_json,'$.createdAt.millis') END),doc_id) WHERE collection='posts';
